def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    # Endgame
    if n >= 99:
        return 'D'
    if n == 98:
        if opp[-1] == 'D':
            return 'D'
        if opp_def == 0:
            return 'D'
        return 'C'

    # Exploit mode: opponent has never defected and we have probed
    if opp_def == 0 and my_def > 0 and n >= 25:
        if n % 5 == 0:
            return 'C'
        else:
            return 'D'

    # Probe
    if n == 20 and opp_def == 0 and my_def == 0:
        return 'D'

    # Base strategy
    if n < 10:
        if opp[-1] == 'D' and my[-1] == 'C':
            return 'D'
        return 'C'

    opp_c = n - opp_def
    opp_rate = opp_c / n
    recent = history[-10:]
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_opp_c = 10 - recent_opp_d

    if recent_opp_d >= 8:
        return 'D'
    if recent_opp_c >= 9:
        return 'C'
    if opp_rate >= 0.8:
        return 'C'
    if opp_rate <= 0.3:
        return 'D'
    if my[-1] == 'C' and opp[-1] == 'D':
        return 'D'
    if my[-1] == 'D' and opp[-1] == 'C':
        return 'C'

    if my[-1] == 'D' and opp[-1] == 'D':
        if n >= 20:
            last20 = history[-20:]
            d_after_d = sum(1 for i in range(1, len(last20)) if last20[i-1][1] == 'D' and last20[i][1] == 'D')
            if d_after_d >= 5:
                return 'D'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    if opp_rate > 0.5:
        return 'C'
    return 'C' if rng.random() < 0.5 else 'D'
